def get_transport_db_entry(dest_slug):
    slug = (dest_slug or '').lower().strip()
    if slug in TRANSPORTATION_DATABASE:
        return TRANSPORTATION_DATABASE[slug]
    return {'name': dest_slug.title(), 'auto': {'name': 'Auto Rickshaw', 'short': (50, 100), 'long': (200, 400), 'full_day': (800, 1200), 'capacity': 3, 'unit': 'vehicle'}, 'bus': {'name': 'Local Bus', 'single': (10, 30), 'daily_pass': (50, 80), 'capacity': 1, 'unit': 'per_person'}, 'cab': {'name': 'Private Cab', 'short': (120, 250), 'long': (300, 600), 'full_day': (1600, 2500), 'capacity': 4, 'unit': 'vehicle'}, 'walking': {'name': 'Foot Trail Walk', 'short': (0, 0), 'capacity': 1, 'unit': 'per_person'}}

def get_destination_attractions(dest_slug):
    slug = (dest_slug or '').lower().strip()
    if slug in DESTINATION_ATTRACTIONS:
        return DESTINATION_ATTRACTIONS[slug]
    return DESTINATION_ATTRACTIONS.get('jaipur', [])

def calculate_group_transport_cost(mode_info, distance_tier='short', travellers=1, is_per_person=False):
    travellers = max(1, int(travellers))
    unit = mode_info.get('unit', 'vehicle')
    capacity = max(1, int(mode_info.get('capacity', 4)))
    if 'fare_inr' in mode_info:
        fare_val = mode_info['fare_inr']
        min_rate = fare_val if isinstance(fare_val, (int, float)) else fare_val[0]
        max_rate = fare_val if isinstance(fare_val, (int, float)) else fare_val[1]
        avg_rate = (min_rate + max_rate) / 2.0
    else:
        fare_range = mode_info.get(distance_tier)
        if not fare_range:
            for k in ['short', 'single', 'medium', 'long', 'trip', 'local', 'point_to_point', 'rowing']:
                if k in mode_info and isinstance(mode_info[k], tuple):
                    fare_range = mode_info[k]
                    break
        if not fare_range:
            fare_range = (50, 100)
        min_rate, max_rate = fare_range
        avg_rate = (min_rate + max_rate) / 2.0
    if unit == 'per_person' or is_per_person:
        total_cost = int(round(avg_rate * travellers))
        fare_per_person = int(round(avg_rate))
        display_fare = f'₹{int(avg_rate)}/person'
    else:
        vehicles_needed = math.ceil(travellers / capacity)
        single_vehicle_cost = int(round(avg_rate))
        total_cost = single_vehicle_cost * vehicles_needed
        fare_per_person = int(round(total_cost / travellers))
        if capacity > 1:
            if vehicles_needed == 1:
                display_fare = f'₹{single_vehicle_cost} (up to {capacity} seats)'
            else:
                display_fare = f'₹{single_vehicle_cost}/vehicle ({vehicles_needed} vehicles needed)'
        else:
            display_fare = f'₹{single_vehicle_cost}'
    return {'min_rate': min_rate, 'max_rate': max_rate, 'avg_rate': avg_rate, 'fare_per_person': fare_per_person, 'total_group_cost': total_cost, 'display_fare': display_fare, 'unit': unit, 'capacity': capacity, 'vehicles_needed': math.ceil(travellers / capacity) if unit in ['vehicle', 'per_vehicle'] else travellers}

def select_best_transport(dest_slug, from_place, to_place, budget_tier, travellers, is_walkable=False, special_transport=None, modifier='normal'):
    dest_data = get_transport_db_entry(dest_slug)
    budget_tier = (budget_tier or 'standard').lower().strip()
    if budget_tier in ['budget', 'backpacker']:
        tier_cat = 'budget'
    elif budget_tier in ['premium', 'luxury']:
        tier_cat = 'premium'
    else:
        tier_cat = 'comfort'
    if modifier == 'cheaper':
        tier_cat = 'budget'
    elif modifier == 'comfortable':
        tier_cat = 'premium'
    if special_transport == 'jeep' and 'jeep' in dest_data:
        j_info = dest_data['jeep']
        cost = calculate_group_transport_cost(j_info, 'trip', travellers)
        return {'mode': 'jeep', 'icon': '🚙', 'provider': j_info.get('name', '4x4 Mountain Jeep'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': f"4x4 Mountain Jeep (Seats up to {j_info.get('capacity', 6)})", 'is_special': True, 'driver_details': get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=j_info.get('capacity', 6))}
    if special_transport == 'ferry' and 'ferry' in dest_data:
        f_info = dest_data['ferry']
        distance_key = 'govt_ferry' if tier_cat == 'budget' else 'private_ferry'
        cost = calculate_group_transport_cost(f_info, distance_key, travellers, is_per_person=True)
        return {'mode': 'ferry', 'icon': '⛴️', 'provider': f_info.get('name', 'Inter-Island Ferry'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': 'Ferry Cruise' if tier_cat == 'premium' else 'Budget Island Ferry', 'is_special': True, 'driver_details': get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=40)}
    if special_transport == 'boat' and 'boat' in dest_data:
        b_info = dest_data['boat']
        boat_tier = 'single' if tier_cat == 'budget' else 'rowing'
        cost = calculate_group_transport_cost(b_info, boat_tier, travellers)
        return {'mode': 'boat', 'icon': '🚣', 'provider': b_info.get('name', 'River / Lake Boat'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': 'Scenic Waterways', 'is_special': True, 'driver_details': get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=6)}
    if is_walkable:
        return {'mode': 'walking', 'icon': '🚶', 'provider': 'Pedestrian Heritage Walk', 'route_text': f'{from_place} → {to_place}', 'fare_per_person': 0, 'group_cost': 0, 'fare_display': 'Free (Walking)', 'tag': 'Eco & Walkable', 'is_special': False}
    if tier_cat == 'budget':
        if 'metro' in dest_data:
            m_info = dest_data['metro']
            cost = calculate_group_transport_cost(m_info, 'single', travellers, is_per_person=True)
            return {'mode': 'metro', 'icon': '🚇', 'provider': m_info.get('name', 'City Metro'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': 'Fast & Economical', 'is_special': False, 'driver_details': get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=50)}
        elif 'bus' in dest_data:
            b_info = dest_data['bus']
            cost = calculate_group_transport_cost(b_info, 'single', travellers, is_per_person=True)
            return {'mode': 'bus', 'icon': '🚍', 'provider': b_info.get('name', 'Local Bus'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': 'Budget Friendly', 'is_special': False, 'driver_details': get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=b_info.get('capacity', 40))}
        elif 'shared' in dest_data:
            s_info = dest_data['shared']
            cost = calculate_group_transport_cost(s_info, 'single', travellers, is_per_person=True)
            return {'mode': 'shared', 'icon': '🛺', 'provider': s_info.get('name', 'Shared Auto / Vikram'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': 'Shared Transit', 'is_special': False, 'driver_details': get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=s_info.get('capacity', 6))}
        else:
            a_info = dest_data.get('auto', {})
            cost = calculate_group_transport_cost(a_info, 'short', travellers)
            return {'mode': 'auto', 'icon': '🛺', 'provider': a_info.get('name', 'Auto Rickshaw'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': 'Economical Auto', 'is_special': False, 'driver_details': get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=a_info.get('capacity', 3))}
    elif tier_cat == 'comfort':
        a_info = dest_data.get('auto', {})
        c_info = dest_data.get('cab', {})
        if travellers >= 3 and c_info:
            cost = calculate_group_transport_cost(c_info, 'short', travellers)
            return {'mode': 'cab', 'icon': '🚕', 'provider': c_info.get('name', 'Private Cab'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': 'Comfortable Group Cab', 'is_special': False, 'driver_details': get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=c_info.get('capacity', 4))}
        else:
            cost = calculate_group_transport_cost(a_info, 'short', travellers)
            return {'mode': 'auto', 'icon': '🛺', 'provider': a_info.get('name', 'Private Auto'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': 'Direct & Convenient', 'is_special': False, 'driver_details': get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=a_info.get('capacity', 3))}
    else:
        c_info = dest_data.get('cab', {})
        cost = calculate_group_transport_cost(c_info, 'long' if 'long' in c_info else 'short', travellers)
        res = {'mode': 'cab', 'icon': '🚕', 'provider': c_info.get('name', 'Chauffeur Cab'), 'route_text': f'{from_place} → {to_place}', 'fare_per_person': cost['fare_per_person'], 'group_cost': cost['total_group_cost'], 'fare_display': cost['display_fare'], 'tag': 'Dedicated Chauffeur Cab', 'is_special': False}
        res['driver_details'] = get_driver_and_cab_details(dest_slug, f'{from_place} → {to_place}', capacity=c_info.get('capacity', 4))
        return res
